WITH blk AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_BLOK blok, DATE_TRUNC('month',BULAN)::DATE mo, MAX(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',1,0)) tm FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4), har AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, DATE_TRUNC('month',BULAN)::DATE mo, SUM(COALESCE(HEKTAR_PANEN,0)) hapan FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3), tonm AS (SELECT DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) ba, p.KODE_AFD afd, DATE_TRUNC('month',p.TANGGAL_PANEN)::DATE mo, SUM(IFF(b.tm=1,p.TON_AKTUAL,0)) tontm FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN p LEFT JOIN blk b ON b.ba=DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) AND b.afd=p.KODE_AFD AND b.blok=p.KODE_BLOK AND b.mo=DATE_TRUNC('month',p.TANGGAL_PANEN)::DATE WHERE p.KODE_BA IN ('2121','2124','2131','2122') AND p.TANGGAL_PANEN>='2026-01-01' AND p.TANGGAL_PANEN<'2026-10-01' GROUP BY 1,2,3), mm AS (SELECT har.ba, har.afd, har.mo, har.hapan, COALESCE(t.tontm,0) tontm FROM har LEFT JOIN tonm t ON t.ba=har.ba AND t.afd=har.afd AND t.mo=har.mo), pd AS (SELECT 'Y' p, DATE '2026-01-01' s, DATE '2026-09-01' e, 9 n UNION ALL SELECT 'M', DATE '2026-09-01', DATE '2026-09-01', 1 UNION ALL SELECT 'A', DATE '2026-01-01', DATE '2026-08-01', 8) SELECT mm.ba, mm.afd, pd.p, ROUND(SUM(hapan)/MAX(pd.n),1) hapan, ROUND(SUM(tontm),1) tontm FROM mm JOIN pd ON mm.mo BETWEEN pd.s AND pd.e GROUP BY mm.ba, mm.afd, pd.p ORDER BY 1,2,3